from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[1];out=root/'public/si-v2'
def read(n):return json.loads((root/n).read_text(encoding='utf8'))
def save(n,v):(root/n).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf8',newline='\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
data=read('public/si-v2/brand-data.json');system=read('brand-system.json');system['version']='2.0-proposal';system['stage']='proposed_replacement';system['creative_direction']={'name':'Uma nova dimensão','theme':'dark-first','light_mode':True,'preserved':['SNPS master','black and white'],'materials':['liquid glass','optical clear','polished silver','frost','solid'],'tool_colors':'Native tool logos in contextual applications; not a brand accent.','supersedes':'Proposal 1.0 rejected by Caio.'}
system['identity']['variants']=[{'id':p.stem,'file':str(p.relative_to(root)).replace('\\','/'),'status':'proposed'} for p in sorted((out/'logos').glob('*.svg'))];system['identity']['colors']=data['palette'];system['identity']['fonts']=[{'family':f,'file':str(p.relative_to(root)).replace('\\','/'),'sha256':sha(p),'license_file':str((p.parent/lic).relative_to(root)).replace('\\','/')} for f,p,lic in [('Manrope',out/'fonts/Manrope.ttf','OFL.txt'),('JetBrains Mono',out/'fonts/JetBrainsMono-Regular.ttf','jetbrainsmono-OFL.txt')]]
system['identity']['contrast_pairs']=[{'id':'dark-primary','foreground':'#F5F5F5','background':'#0A0A0A','minimum':4.5,'surface':'solid'},{'id':'light-primary','foreground':'#171719','background':'#F5F5F7','minimum':4.5,'surface':'solid'},{'id':'dark-muted','foreground':'#A6A6AA','background':'#0A0A0A','minimum':4.5,'surface':'solid'},{'id':'light-muted','foreground':'#626267','background':'#F5F5F7','minimum':4.5,'surface':'solid'}]
system['editorial']['families']=data['editorialFamilies'];system['transition']={'preserved':['SNPS original','ofertas e fontes factuais'],'changed':['navegação','tipografia','assinaturas','ícones','materiais','motion','editorial','fotografia de roupas'],'rollout':['revisar proposta 02','aplicar em lote autorizado','conferir no destino'],'recovery':'Git 29b033b preserva a proposta anterior; originais em public/brand/logo.'};save('brand-system.json',system)
brief=read('brief.json');brief['objective']='Substituir integralmente a proposta visual anterior, preservando SNPS e preto e branco. Dark First, Light Mode, materiais ópticos, logos dos quatro braços, ícones novos, ferramentas coloridas e roupas realistas inspiradas na Coinbase Shop.';brief['constraints']['preserve']=['SNPS original','preto e branco'];brief['constraints']['change_requested']=system['transition']['changed'];save('brief.json',brief)
corp=read('corporate-brand.json');corp['transition']=system['transition']['rollout'];corp['governance']['source_of_truth']='CANON.md + brand-system.json + components/si-v2 + public/si-v2';save('corporate-brand.json',corp)
digital=read('digital-product.json');digital['implementation_status']='implemented_local_preview_v2';digital['semantic_tokens']=[{'dark':{'background':'#0A0A0A','foreground':'#F5F5F5'},'light':{'background':'#F5F5F7','foreground':'#171719'}}];save('digital-product.json',digital)
ed=read('editorial.json');ed['families']=data['editorialFamilies'];ed['posts']=data['sequenceT04'];ed['status']='proposal_02';save('editorial.json',ed)
dec=read('decisions.json');dec['decisions']=[d for d in dec['decisions'] if d['id'] not in ['SI-PROPOSAL','SI-V2']]+[{'id':'SI-PROPOSAL','status':'rejected','decision':'Proposta visual 1.0 rejeitada por Caio.'},{'id':'SI-V2','status':'awaiting_review','decision':'Proposta 02: Dark First + Light Mode; materiais ópticos, novas assinaturas e ícones, mockups realistas, cor de ferramentas em contexto.'}];save('decisions.json',dec)
book=read('roteiro-brandbook.json');book['format']['slide_count']=37;book['file']='public/si-v2/SINAPSE-SI-Brandbook-02.pdf';book['source']='scripts/build-si-v2-book.py';save('roteiro-brandbook.json',book)
manifest=read('asset-manifest.json');assets=[]
for p in sorted(out.rglob('*')):
    if not p.is_file() or p.suffix not in ['.svg','.webp','.pdf']:continue
    role='brandbook-pdf' if p.suffix=='.pdf' else 'social-slide' if p.parent.name=='templates' else 'identity-variant' if p.parent.name=='logos' else 'brand-expression'
    assets.append({'id':'v2-'+str(p.relative_to(out)).replace('\\','-').replace('/','-'),'file':str(p.relative_to(root)).replace('\\','/'),'kind':'pdf' if p.suffix=='.pdf' else 'image','role':role,'sha256':sha(p),'status':'proposed'})
