save('public/si-v2/tokens.json',{'version':2,'themes':digital['semantic_tokens'][0],'palette':data['palette'],'type':{'display':'Manrope 600','text':'Manrope 400','metadata':'JetBrains Mono 400'},'motion':data['motionRules'],'glass':{'blur_px':28,'control_radius_px':100,'panel_radius_px':28},'tool_colors':'Contextual brand assets; not SINAPSE palette.'})
